import { ok, fail } from './result.js';
import { roundCents } from './money.js';
import { getCustomer, normalizeId, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Validate and normalize a discount percentage.
 * @param {unknown} discountPercent
 * @returns {{ ok: true } | { ok: false, error: string }}
 */
function validateDiscount(discountPercent) {
  if (discountPercent === undefined || discountPercent === null) return { ok: true };
  if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
    return { ok: false, error: 'DISCOUNT_INVALID' };
  }
  return { ok: true };
}

/**
 * Calculate the discount amount for a line (in cents, rounded).
 * @param {number} lineTotal - Total before discount (in cents)
 * @param {number} discountPercent - Discount percentage (0-100)
 * @returns {number} Discount amount in cents
 */
function calculateLineDiscount(lineTotal, discountPercent) {
  if (!discountPercent) return 0;
  return roundCents((lineTotal * discountPercent) / 100);
}

/**
 * Create an invoice for a customer with line items from the catalogue.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: 'draft', lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  // Validate issueDate format and reality
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate lines array is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and expand all line items
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discount
    const discountValidation = validateDiscount(line.discountPercent);
    if (!discountValidation.ok) return fail(discountValidation.error);

    // Look up product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;

    // Apply tier discount if no explicit discount is provided
    const discountPercent =
      line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];

    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Calculate the total price of a line item (qty × unitPrice).
 * @param {{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }}
 * @returns {number} Total in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the amount of a line after its discount.
 * @param {number} lineTot - Total before discount
 * @param {number} discountPercent - Discount percentage
 * @returns {number} Amount after discount in cents
 */
function lineAmountAfterDiscount(lineTot, discountPercent) {
  const discount = calculateLineDiscount(lineTot, discountPercent);
  return lineTot - discount;
}

/**
 * Calculate the VAT for a line (on the amount after discount).
 * @param {number} amountAfterDiscount - Amount after discount
 * @param {number} vatRate - VAT rate in percent (0, 9, or 21)
 * @returns {number} VAT amount in cents (rounded)
 */
function calculateLineVat(amountAfterDiscount, vatRate) {
  if (!vatRate || vatRate === 0) return 0;
  return roundCents((amountAfterDiscount * vatRate) / 100);
}

/**
 * Calculate the totals for an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }}
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }} Amounts in cents
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => {
    const lineTot = lineTotal(line);
    return sum + calculateLineDiscount(lineTot, line.discountPercent || 0);
  }, 0);
  const vat = invoice.lines.reduce((sum, line) => {
    const lineTot = lineTotal(line);
    const amountAfterDiscount = lineAmountAfterDiscount(lineTot, line.discountPercent || 0);
    return sum + calculateLineVat(amountAfterDiscount, line.vatRate);
  }, 0);
  const total = Math.max(0, subtotal - discount + vat);

  return {
    subtotal,
    discount,
    vat,
    total,
  };
}

/**
 * Add a line to a draft invoice. If the SKU already exists, increase its qty.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} item
 * @returns {{ ok: true, value: { customerId, issueDate, status, lines } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  const discountValidation = validateDiscount(discountPercent);
  if (!discountValidation.ok) return fail(discountValidation.error);

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex].qty += qty;
  } else {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discountPercent || 0,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { customerId, issueDate, status, lines } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((_, index) => index !== lineIndex);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string[]} existingNumbers - Array of invoice numbers already issued
 * @returns {{ ok: true, value: { number: string, customerId, issueDate, status: 'issued', lines } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    number,
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

/**
 * Check if a date string is a valid date in YYYY-MM-DD format.
 * @param {string} dateString
 * @returns {boolean}
 */
function isValidDate(dateString) {
  if (typeof dateString !== 'string') return false;
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.test(dateString);
  if (!match) return false;
  const date = new Date(dateString + 'T00:00:00Z');
  return date instanceof Date && !isNaN(date.getTime()) && date.toISOString().startsWith(dateString);
}

